create unique index if not exists income_sources_user_kind_name_uq on public.income_sources(user_id,kind,name);
create or replace function public.create_card_purchase(p_card_id uuid,p_category_id text,p_description text,p_total_minor bigint,p_purchased_on date,p_installment_count integer,p_is_avoidable boolean default false) returns uuid language plpgsql security invoker set search_path='' as $$declare uid uuid:=auth.uid();purchase_id uuid;base_amount bigint;remainder bigint;i integer;amount_i bigint;first_month date;card_closing_day integer;begin if uid is null then raise exception 'not authenticated';end if;if p_total_minor<=0 or p_installment_count<1 then raise exception 'invalid purchase';end if;select c.closing_day into card_closing_day from public.credit_cards c where c.id=p_card_id and c.user_id=uid;if not found then raise exception 'invalid card';end if;insert into public.card_purchases(user_id,card_id,category_id,description,total_minor,purchased_on,installment_count,is_avoidable) values(uid,p_card_id,p_category_id,nullif(trim(p_description),''),p_total_minor,p_purchased_on,p_installment_count,p_is_avoidable) returning id into purchase_id;base_amount:=p_total_minor/p_installment_count;remainder:=p_total_minor%p_installment_count;first_month:=date_trunc('month',p_purchased_on)::date;if card_closing_day is not null and extract(day from p_purchased_on)::integer>card_closing_day then first_month:=(first_month+interval '1 month')::date;end if;for i in 1..p_installment_count loop amount_i:=base_amount+case when i<=remainder then 1 else 0 end;insert into public.card_installments(user_id,purchase_id,installment_number,amount_minor,billing_month) values(uid,purchase_id,i,amount_i,(first_month+make_interval(months=>i-1))::date);end loop;return purchase_id;end;$$;
revoke all on function public.create_card_purchase(uuid,text,text,bigint,date,integer,boolean) from public,anon;grant execute on function public.create_card_purchase(uuid,text,text,bigint,date,integer,boolean) to authenticated;
